package vn.smarttravel.catalog.infrastructure.events.repository;
import java.util.*;
import com.fasterxml.jackson.databind.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import vn.smarttravel.catalog.places.repository.CatalogRepository;
import vn.smarttravel.catalog.infrastructure.persistence.repository.IdempotencyRepository;
import vn.smarttravel.catalog.infrastructure.events.client.SourcePolicyClient;

@Repository
public class EventRepository {
    private final JdbcTemplate db;private final CatalogRepository places;private final IdempotencyRepository idempotency;private final SourcePolicyClient policy;private final ObjectMapper json;private final TransactionTemplate nested;
    public EventRepository(JdbcTemplate db,CatalogRepository places,IdempotencyRepository idempotency,SourcePolicyClient policy,ObjectMapper json,PlatformTransactionManager manager){this.db=db;this.places=places;this.idempotency=idempotency;this.policy=policy;this.json=json;nested=new TransactionTemplate(manager);nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);}
    public boolean userAllowed(UUID user){var rows=db.queryForList("SELECT status FROM catalog.user_status_projections WHERE user_id=?",user);return rows.isEmpty()||rows.getFirst().get("status").equals("ACTIVE");}
    private UUID uuid(Map<String,Object> payload,String field){return UUID.fromString(Objects.toString(payload.get(field),""));}
    @Transactional public boolean accept(JsonNode event){
        UUID id=UUID.fromString(event.path("event_id").asText());String type=event.path("event_type").asText();if(event.path("schema_version").asInt()!=1||!event.path("payload").isObject())throw new IllegalArgumentException("Invalid event envelope");
        String producer=event.path("producer").asText();String expected=type.startsWith("community.")?"community":type.startsWith("identity.")?"identity":"ingestion";if(!expected.equals(producer))throw new IllegalArgumentException("Unexpected event producer");
        if(db.update("INSERT INTO catalog.inbox_events(consumer_name,event_id) VALUES('domain',?) ON CONFLICT DO NOTHING",id)==0)return false;
        @SuppressWarnings("unchecked")Map<String,Object> payload=json.convertValue(event.path("payload"),Map.class);
        switch(type){
            case "community.rating-summary.changed.v1"->places.rating(id,payload);
            case "identity.user.status-changed.v1"->{vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.lock(db,uuid(payload,"user_id"));db.update("INSERT INTO catalog.user_status_projections(user_id,status,source_version) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET status=excluded.status,source_version=excluded.source_version,updated_at=now() WHERE excluded.source_version>catalog.user_status_projections.source_version",uuid(payload,"user_id"),payload.get("status"),payload.get("version"));}
            case "identity.user.deletion-requested.v1"->delete(payload);
            case "ingestion.source-policy.changed.v1"->sourcePolicy(payload);
            case "ingestion.place.upsert-requested.v1","community.contribution.apply-requested.v1"->{UUID command=uuid(payload,"command_id");idempotency.execute(producer,"command",command.toString(),payload,()->command(type,payload));}
            default->throw new IllegalArgumentException("Unsupported Catalog event");
        }
        return true;
    }
    private Object command(String type,Map<String,Object> payload){boolean imported=type.startsWith("ingestion.");UUID command=uuid(payload,"command_id");UUID aggregate=imported?command:uuid(payload,"contribution_id");UUID source=imported?uuid(payload,"source_id"):null;UUID actor=imported?null:uuid(payload,"approved_by");long expected=((Number)payload.get(imported?"expected_catalog_version":"expected_version")).longValue();UUID place=imported?uuid(payload,"proposed_place_id"):payload.get("target_id")==null?UUID.randomUUID():uuid(payload,"target_id");
        if(imported){var current=policy.policy(source);sourcePolicy(current);var stored=db.queryForMap("SELECT status,allow_storage,source_version FROM catalog.source_policy_projections WHERE source_id=?",source);if(!"PERMITTED".equals(stored.get("status"))||!Boolean.TRUE.equals(stored.get("allow_storage")))return rejected(imported,aggregate,payload,"SOURCE_REVOKED","Source policy forbids storage");if(((Number)current.get("source_version")).longValue()<((Number)payload.get("source_version")).longValue())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Policy version not yet available");}
        @SuppressWarnings("unchecked")Map<String,Object> fields=new LinkedHashMap<>((Map<String,Object>)payload.get(imported?"normalized":"fields"));if(fields.containsKey("price"))fields.put("price_min",fields.remove("price"));
        try{Map<String,Object> result=nested.execute(status->{var exists=db.queryForList("SELECT version FROM catalog.places WHERE place_id=? FOR UPDATE",place);if(exists.isEmpty()){if(expected!=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Expected place does not exist");fields.put("place_id",place);if(!fields.containsKey("geographic_unit_id")){Object lat=fields.getOrDefault("latitude",fields.get("lat")),lon=fields.getOrDefault("longitude",fields.get("lon"));var geos=db.queryForList("SELECT geographic_unit_id,name_vi FROM catalog.geographic_units WHERE status='ACTIVE' AND valid_from<=current_date AND (valid_to IS NULL OR valid_to>=current_date) AND boundary IS NOT NULL AND ST_Covers(boundary,ST_SetSRID(ST_MakePoint(?,?),4326)) ORDER BY CASE unit_type WHEN 'WARD' THEN 0 WHEN 'DISTRICT' THEN 1 WHEN 'PROVINCE' THEN 2 ELSE 3 END LIMIT 1",lon,lat);if(geos.isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Geographic scope unresolved");fields.put("geographic_unit_id",geos.getFirst().get("geographic_unit_id"));fields.putIfAbsent("address",geos.getFirst().get("name_vi"));}var created=new CatalogRepository(db,json).create(fields,actor);var ranks=new LinkedHashMap<String,Integer>();for(String field:places.aliases(fields).keySet())ranks.put(field,imported?1:2);try{db.update("UPDATE catalog.places SET field_precedence=?::jsonb WHERE place_id=?",json.writeValueAsString(ranks),place);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalArgumentException(e);}return created;}long actual=((Number)exists.getFirst().get("version")).longValue();if(actual!=expected)throw new ResponseStatusException(HttpStatus.CONFLICT,"Expected place version conflict");return new CatalogRepository(db,json).updateAtPriority(place,expected,fields,actor,imported?1:2);});
            long version=((Number)result.get("version")).longValue();if(version!=expected)db.update("UPDATE catalog.place_versions SET source_id=?,source_command_id=? WHERE place_id=? AND version_no=? AND source_command_id IS NULL",source,command,place,version);var response=new LinkedHashMap<String,Object>();response.put("command_id",command);response.put(imported?"source_id":"contribution_id",imported?source:aggregate);response.put("place_id",place);response.put(imported?"catalog_version":"version",version);places.emit(imported?"catalog.place-import.applied.v1":"catalog.contribution.applied.v1",aggregate,version,response);return response;
        }catch(ResponseStatusException error){return rejected(imported,aggregate,payload,"PROTECTED_FIELD_CONFLICT".equals(error.getReason())?"PROTECTED_FIELD_CONFLICT":error.getStatusCode().value()==409?"VERSION_CONFLICT":"INVALID_FIELDS",Objects.toString(error.getReason(),"Command rejected"));}catch(org.springframework.dao.DataIntegrityViolationException error){return rejected(imported,aggregate,payload,"INVALID_FIELDS","Canonical data constraint rejected");}
    }
    private Object rejected(boolean imported,UUID aggregate,Map<String,Object> command,String code,String reason){var response=new LinkedHashMap<String,Object>();response.put("command_id",command.get("command_id"));response.put(imported?"source_id":"contribution_id",command.get(imported?"source_id":"contribution_id"));response.put("error_code",code);response.put("reason",reason);places.emit(imported?"catalog.place-import.rejected.v1":"catalog.contribution.rejected.v1",aggregate,1,response);return response;}
    private void sourcePolicy(Map<String,Object> payload){UUID source=uuid(payload,"source_id");int changed=db.update("INSERT INTO catalog.source_policy_projections(source_id,status,allow_storage,source_version) VALUES(?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET status=excluded.status,allow_storage=excluded.allow_storage,source_version=excluded.source_version,updated_at=now() WHERE excluded.source_version>catalog.source_policy_projections.source_version",source,payload.get("status"),payload.get("allow_storage"),payload.get("source_version"));if(changed>0&&(!Boolean.TRUE.equals(payload.get("allow_storage"))||"REVOKED".equals(payload.get("status")))){db.update("UPDATE catalog.media_assets SET moderation_status='REJECTED' WHERE source_id=?",source);for(var row:db.queryForList("SELECT p.place_id,p.version FROM catalog.places p JOIN catalog.place_versions v ON v.place_id=p.place_id AND v.version_no=p.version WHERE v.source_id=? AND p.status='PUBLISHED' FOR UPDATE OF p",source))places.updateAtPriority((UUID)row.get("place_id"),((Number)row.get("version")).longValue(),Map.of("status","HIDDEN"),null,4);}}
    private void delete(Map<String,Object> payload){UUID user=uuid(payload,"user_id"),request=uuid(payload,"deletion_request_id");vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.lock(db,user);UUID anonymous=UUID.nameUUIDFromBytes(("catalog-deleted:"+user).getBytes(java.nio.charset.StandardCharsets.UTF_8));db.update("INSERT INTO catalog.user_status_projections(user_id,status,source_version) VALUES(?,'DELETED',9223372036854775807) ON CONFLICT(user_id) DO UPDATE SET status='DELETED',source_version=excluded.source_version",user);db.update("UPDATE catalog.business_place_claims SET status='REVOKED',reason='Owner deleted' WHERE business_id IN (SELECT business_id FROM catalog.businesses WHERE owner_user_id=?)",user);db.update("UPDATE catalog.businesses SET owner_user_id=?,contact_email=NULL,contact_phone=NULL,legal_name=NULL,verification_status='SUSPENDED',version=version+1 WHERE owner_user_id=?",anonymous,user);db.update("DELETE FROM catalog.business_members WHERE user_id=?",user);db.update("UPDATE catalog.places SET created_by=NULL WHERE created_by=?",user);db.update("UPDATE catalog.media_assets SET created_by=NULL,moderation_status=CASE WHEN object_key LIKE 'private/%' THEN 'REJECTED' ELSE moderation_status END WHERE created_by=?",user);db.update("UPDATE catalog.place_versions SET created_by=NULL WHERE created_by=?",user);places.emit("domain.user-data-deleted.v1",request,1,Map.of("deletion_request_id",request,"service","catalog","status","COMPLETED","artifact_handling","Business contacts scrubbed, memberships removed, claims revoked, creator references removed; canonical place history retained"));}
}
